<?php
if (!defined('ABSPATH')) exit;
function msfp_tenant_unit_id($user_id){$u=function_exists('ms_get_tenant_unit')?ms_get_tenant_unit($user_id):null;return absint($u->unit_id??$u->id??0);}
function msfp_tenant_overview($user_id){$next=function_exists('ms_get_latest_due_invoice')?ms_get_latest_due_invoice($user_id):null;$name=wp_get_current_user()->display_name;ob_start();?><section class="msfp-tenant-panel" dir="rtl"><div class="msfp-welcome"><span>أهلًا بك</span><h2><?php echo esc_html($name); ?></h2><p>نتمنى لك إقامة مريحة. نتابع معك الإيجار والصيانة والمستندات من مكان واحد.</p></div><?php if($next):?><div class="msfp-rent-reminder"><strong>موعد دفع الإيجار القادم</strong><b><?php echo esc_html($next->due_date); ?></b><span>المبلغ: <?php echo esc_html(number_format_i18n((float)$next->amount,2)); ?> ج.م</span></div><?php else:?><div class="msfp-empty-row">لا يوجد موعد إيجار قادم مسجل حاليًا.</div><?php endif;?></section><?php return ob_get_clean();}
function msfp_tenant_maintenance($user_id){global $wpdb;$unit=msfp_tenant_unit_id($user_id);$rows=$unit?$wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ms_maintenance_requests WHERE unit_id=%d ORDER BY created_at DESC LIMIT 100",$unit)):array();$groups=array('active'=>array(),'completed'=>array(),'cancelled'=>array());foreach((array)$rows as $r){$s=sanitize_key($r->status??'open');$g=in_array($s,array('cancelled','canceled','rejected','deleted'),true)?'cancelled':(in_array($s,array('completed','complete','closed','done'),true)?'completed':'active');$groups[$g][]=$r;}ob_start();?><section class="msfp-tenant-panel" dir="rtl"><div class="msfp-panel-heading"><div><span>المرافق</span><h2>طلبات الصيانة</h2><p>الصيانات النشطة والمنتهية والملغية المرتبطة بوحدتك.</p></div></div><div class="msfp-status-sections"><?php foreach(array('active'=>'نشطة','completed'=>'منتهية','cancelled'=>'ملغية') as $key=>$label):?><div class="msfp-maint-section"><h3><?php echo esc_html($label);?><em><?php echo count($groups[$key]);?></em></h3><?php if(!$groups[$key]):?><div class="msfp-empty-row">لا توجد طلبات.</div><?php else:foreach($groups[$key] as $r):$invoice=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ms_invoices WHERE user_id=%d AND expense_id=%d AND status NOT IN ('paid','canceled','cancelled') ORDER BY id DESC LIMIT 1",$user_id,absint($r->id)));?><article class="msfp-maint-row"><div><strong><?php echo esc_html($r->title?:'طلب صيانة');?></strong><small><?php echo esc_html($r->created_at);?></small></div><div><span><?php echo esc_html(number_format_i18n((float)$r->cost,2));?> ج.م</span><?php if($invoice):?><button class="msfp-tenant-pay" data-invoice-id="<?php echo intval($invoice->id);?>" data-nonce="<?php echo esc_attr(wp_create_nonce('ms_pay_invoice_'.intval($invoice->id)));?>">دفع الرسوم</button><?php endif;?></div></article><?php endforeach;endif;?></div><?php endforeach;?></div></section><?php return ob_get_clean();}
function msfp_tenant_deposit($user_id){global $wpdb;$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ms_security_deposits WHERE tenant_id=%d ORDER BY id DESC",$user_id));ob_start();?><section class="msfp-tenant-panel" dir="rtl"><div class="msfp-panel-heading"><span>الضمان المالي</span><h2>تأمين الأمانة</h2><p>هو مبلغ ضمان يُجمّد لحماية حقوق المالك والمستأجر أثناء مدة الإيجار. عند انتهاء العلاقة الإيجارية يُعاد للمستأجر بعد خصم أي أضرار مثبتة ومصرح بها.</p></div><?php if(!$rows):?><div class="msfp-empty-row">لا يوجد سجل تأمين أمانة مرتبط بك حاليًا.</div><?php else:?><div class="msfp-deposit-list"><?php foreach($rows as $r):?><div><strong><?php echo esc_html(number_format_i18n((float)$r->amount,2));?> ج.م</strong><span class="msfp-deposit-<?php echo esc_attr($r->status);?>"><?php echo esc_html($r->status);?></span><small><?php echo esc_html($r->created_at);?></small></div><?php endforeach;?></div><?php endif;?></section><?php return ob_get_clean();}
function msfp_tenant_documents($user_id){global $wpdb;$docs=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ms_documents WHERE user_id=%d ORDER BY id DESC LIMIT 100",$user_id));$colors=array('lease_contract'=>'#dbeafe','identity'=>'#fef3c7','insurance'=>'#dcfce7','other'=>'#f1f5f9');$labels=array('lease_contract'=>'عقد الإيجار','identity'=>'الهوية','insurance'=>'التأمين','other'=>'مستند آخر');ob_start();?><section class="msfp-tenant-panel" dir="rtl"><div class="msfp-panel-heading"><span>ملفاتك</span><h2>المستندات</h2><p>كل نوع مستند مميز بلون، مع صورة مصغرة للصور المرفوعة.</p></div><div class="msfp-doc-grid"><?php if(!$docs):?><div class="msfp-empty-row">لا توجد مستندات مرفوعة.</div><?php else:foreach($docs as $d):$url=$d->file_url?:wp_get_attachment_url(absint($d->file_id));$thumb=wp_get_attachment_image_url(absint($d->file_id),'thumbnail');$type=$d->document_type?:'other';?><a class="msfp-doc-card" style="--doc-color:<?php echo esc_attr($colors[$type]??$colors['other']);?>" href="<?php echo esc_url($url);?>" target="_blank" rel="noopener"><?php if($thumb):?><img src="<?php echo esc_url($thumb);?>" alt=""><?php else:?><span class="msfp-doc-icon">▣</span><?php endif;?><strong><?php echo esc_html($d->title);?></strong><small><?php echo esc_html($labels[$type]??$type);?></small></a><?php endforeach;endif;?></div></section><?php return ob_get_clean();}
function msfp_tenant_meters($user_id){global $wpdb;$unit=msfp_tenant_unit_id($user_id);$rows=$unit?$wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->prefix}ms_meter_readings WHERE unit_id=%d ORDER BY reading_date DESC,id DESC LIMIT 100",$unit)):array();$colors=array('electricity'=>'#fef3c7','water'=>'#dbeafe','gas'=>'#fee2e2');$labels=array('electricity'=>'كهرباء','water'=>'مياه','gas'=>'غاز');ob_start();?><section class="msfp-tenant-panel" dir="rtl"><div class="msfp-panel-heading"><span>الاستهلاك</span><h2>العدادات</h2><p>كل نوع عداد مميز بلون لتسهيل متابعة القراءة.</p></div><div class="msfp-meter-grid"><?php if(!$rows):?><div class="msfp-empty-row">لا توجد قراءات مسجلة.</div><?php else:foreach($rows as $r):$type=$r->meter_type?:'electricity';?><div class="msfp-meter-card" style="--meter-color:<?php echo esc_attr($colors[$type]??'#f1f5f9');?>"><strong><?php echo esc_html($labels[$type]??$type);?></strong><b><?php echo esc_html($r->reading_value);?></b><small><?php echo esc_html($r->reading_date);?></small><?php if(!empty($r->image_url)):?><a href="<?php echo esc_url($r->image_url);?>" target="_blank">عرض صورة العداد</a><?php endif;?></div><?php endforeach;endif;?></div></section><?php return ob_get_clean();}
function msfp_tenant_tab_html($tab,$user_id){switch(sanitize_key($tab)){case'overview':return msfp_tenant_overview($user_id);case'maintenance':return msfp_tenant_maintenance($user_id);case'deposit':return msfp_tenant_deposit($user_id);case'documents':return msfp_tenant_documents($user_id);case'meters':return msfp_tenant_meters($user_id);}return '';}
add_action('wp_ajax_ms_get_tenant_tab',function(){if(!is_user_logged_in()||!check_ajax_referer('mostaager-ajax-nonce','security',false))wp_send_json_error('forbidden',403);$u=wp_get_current_user();if(!function_exists('ms_user_can_view_dashboard')||!ms_user_can_view_dashboard($u->ID,'tenant'))wp_send_json_error('forbidden',403);$tab=sanitize_key($_POST['tab']??'');if(!in_array($tab,array('overview','maintenance','deposit','documents','meters'),true))wp_send_json_error('invalid_tab',400);wp_send_json_success(array('html'=>msfp_tenant_tab_html($tab,$u->ID)));});
